"use client"

import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible"

import { cn } from "@/lib/utils"

/* Trigger is a raised velour bar; the open body settles into a quieter face. */

const Collapsible = CollapsiblePrimitive.Root

// Base UI className can be a state function; narrow it to a plain string so it
// feeds cn() (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

function CollapsibleTrigger({
  className,
  ...props
}: WithClassName<CollapsiblePrimitive.Trigger.Props>) {
  return (
    <CollapsiblePrimitive.Trigger
      className={cn(
        "flex w-full items-center justify-between rounded-lg px-4 py-3",
        "[background-image:var(--velour-raised)] [box-shadow:var(--shadow-button)]",
        "text-sm font-medium text-foreground",
        "transition-[background-image,box-shadow] duration-fast",
        "hover:[background-image:var(--velour-hover)] hover:[box-shadow:var(--shadow-button-hover)]",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/30",
        "[&[data-panel-open]]:rounded-b-none",
        className
      )}
      {...props}
    />
  )
}
CollapsibleTrigger.displayName = "CollapsibleTrigger"

function CollapsibleContent({
  className,
  ...props
}: WithClassName<CollapsiblePrimitive.Panel.Props>) {
  return (
    <CollapsiblePrimitive.Panel
      className={cn(
        "overflow-hidden rounded-b-lg",
        "[background-image:var(--velour)] [box-shadow:var(--shadow-s)]",
        "data-closed:animate-collapsible-up data-open:animate-collapsible-down",
        className
      )}
      {...props}
    />
  )
}
CollapsibleContent.displayName = "CollapsibleContent"

export { Collapsible, CollapsibleTrigger, CollapsibleContent }
